-- The rows inserted by 20260917130000_seed_test_indicators may already have
-- been deployed before positionCode existed on TestIndicator, in which
-- case that migration is checksum-locked as "already applied" and editing
-- its INSERT values has no effect on a database that already ran it. This
-- migration is safe to run regardless: it removes any TestIndicator row
-- missing a positionCode (the old seed data, or nothing at all if the
-- earlier fix already took effect) and re-inserts the full
-- accreditation-scope indicator set with positionCode populated.
DELETE FROM "TestIndicator" WHERE "positionCode" IS NULL;

